window.kbPageData["views/entry/k-72a705667e55a451"] = {"key":"entry/k-72a705667e55a451","state":{"route":"entry/k-72a705667e55a451"},"node":{"id":"k-72a705667e55a451","mode":"k","title":"缄口不言与口若悬河","type":"概念与词义","domain":"汉语","reading":"","intro":"","priority":100,"aliases":["缄口不言与口若悬河的词义辨析"],"qs":["国考 2023 地市级 行测#100"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"缄口不言指闭口不说，常含谨慎、不愿或不敢开口之意。口若悬河形容能说善辩、话语滔滔不绝。","review":{"definition":"缄口不言指闭口不说，常含谨慎、不愿或不敢开口之意。口若悬河形容能说善辩、话语滔滔不绝。","explanation":"D项把闭口不说与滔滔不绝相对，在开口说话的表现上构成反义关系，与后半组的反义关系一致。A项的三缄其口和C项的守口如瓶都与缄口不言有闭口少言的共同点。B项的畅所欲言虽也可与缄口不言相对，但其后半组的放荡不羁与虚怀若谷谈的是不同方面。","references":[],"evidence":"口若悬河意为说话滔滔不绝","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2023 地市级 行测#100":{"paper":"国考 2023 地市级 行测","n":100,"mod":"判断推理","src":["64bc3a15d27a04e94940.pdf",20],"asrc":["f3ab652d8e31c5bbdabc.pdf",32],"card":"99f520a6366db7c5b9effcac","links":[{"id":"k-72a705667e55a451","role":"直接考查","why":"缄口不言指闭口不说，口若悬河指说话滔滔不绝，两者在言语表现上相反。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-72a705667e55a451":[["国考 2023 地市级 行测#100"]]}};
